inline void prepare(const int16_t *samples,float *data){
    int32_t sum=0;for(size_t i=0;i<kSize;++i)sum+=samples[i];
    const float mean=static_cast<float>(sum)/kSize;
    for(size_t i=0;i<kSize;++i){data[2*i]=(static_cast<float>(samples[i])-mean)*kWindowScale[i];data[2*i+1]=0.0f;}
}
// Portable fallback uses the same table and no per-frame trigonometric functions.
inline void portable_fft(float *data){
    // Decimation in frequency, matching the ESP-DSP transform ordering.
    for(size_t span=kSize/2,groups=1;span>0;span>>=1,groups<<=1){
        for(size_t group=0;group<groups;++group){
            const float c=kTwiddle[2*group],s=kTwiddle[2*group+1];
            const size_t base=group*2*span;
            for(size_t i=0;i<span;++i){
                const size_t a=2*(base+i),b=2*(base+i+span);
                const float r=c*data[b]+s*data[b+1],im=c*data[b+1]-s*data[b];
                data[b]=data[a]-r;data[b+1]=data[a+1]-im;data[a]+=r;data[a+1]+=im;
            }
        }
    }
}
inline void bit_reverse(float *data){
    for(size_t i=1,j=0;i<kSize;++i){size_t bit=kSize>>1;for(;(j&bit)!=0;bit>>=1)j^=bit;j^=bit;
        if(i<j){float t=data[2*i];data[2*i]=data[2*j];data[2*j]=t;t=data[2*i+1];data[2*i+1]=data[2*j+1];data[2*j+1]=t;}}
}
inline uint8_t power_level(float power){
    // 20*log10(sqrt(power)/64) == 10*log10(power/(64*64)).
    if(power<4.096e-9f)power=4.096e-9f;
    const float db=10.0f*log10f(power*(1.0f/4096.0f));
    if(db<=-45.0f)return 0;
    if(db>=0.0f)return 255;
    const uint32_t linear=static_cast<uint32_t>((db+45.0f)*(255.0f/45.0f)+0.5f);
    return static_cast<uint8_t>((linear*linear+127U)/255U);
}
